<?php
declare(strict_types=1);
require_once __DIR__ . '/../../lib/mdm_helpers.php';
$u=require_role(['admin','principal','clerk']);$sid=(int)$u['school_id'];$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'&&valid_csrf($_POST['csrf']??null)){$pdo->prepare('REPLACE INTO mdm_pat_history(school_id,class_group,month,year,enrolled,present_days) VALUES(?,?,?,?,?,?)')->execute([$sid,$_POST['class_group'],(int)$_POST['month'],(int)$_POST['year'],(int)$_POST['enrolled'],(int)$_POST['present_days']]);flash_set('success','पट इतिहास जतन झाला.');}$q=$pdo->prepare('SELECT * FROM mdm_pat_history WHERE school_id=? ORDER BY year DESC,month DESC,class_group');$q->execute([$sid]);$rows=$q->fetchAll();mdm_layout_start('पट इतिहास — पोषण आहार');
?>
<form method="post" class="bg-white border rounded-2xl p-6 grid sm:grid-cols-6 gap-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><select name="class_group"><?php foreach(mdm_groups() as $g=>$l):?><option value="<?=$g?>"><?=$l?></option><?php endforeach;?></select><input name="month" type="number" min="1" max="12" value="<?=date('m')?>"><input name="year" type="number" value="<?=date('Y')?>"><input name="enrolled" type="number" placeholder="पट"><input name="present_days" type="number" placeholder="उपस्थित दिवस"><button class="bg-gold rounded-xl">जतन</button></form><div class="bg-white border rounded-2xl p-6 mt-6"><table class="w-full text-sm"><thead><tr><th>महिना</th><th>गट</th><th>पट</th><th>उपस्थित दिवस</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['month']?>/<?=$r['year']?></td><td><?=mdm_groups()[$r['class_group']]?></td><td><?=$r['enrolled']?></td><td><?=$r['present_days']?></td></tr><?php endforeach;?></tbody></table></div>
<?php layout_end(); ?>
